-- Reviewed P99 exchanges using existing quest primitives. Quest faction gating remains intentionally bypassed.
local item_lib = require("items")

function event_say(e)
  if e.message:findi("hail") then
    e.self:Say("Another offlander who has recognized and submitted to the will of Tormax I see in you, " .. e.other:GetCleanName() .. ", and that is a good thing for you indeed. For your service I offer you the option of trading in any plate helm you earned from our smiths for one more suited to your race. Ask about [special helmets].")
  elseif e.message:findi("special helmets") then
    e.self:Say("Just as I suspected " .. e.other:GetRaceName() .. ". Using my superior skills I can customize a plate helmet to help better protect you. Give me your Malevolent Crown, Warlord's Crown, Shining Helm, Templar's Crown, Troubadour's Helm, Frostreaver's Velium Crown, Crown of the Kromzek Kings or a Cowl of Mortality and I shall make you a new helm that will better protect you.")
  end
end

